/**
 * 2D 图纸导出：SVG（P0-6，零依赖）+ PNG（保留原语义，SPEC §F.6 R-EXP-2/R-EXP-3/R-EXP-5）。
 *
 * 关键规则（⛔ 违反即导出丢色，RISK-06）：
 * - **R-EXP-1**：图层里的颜色已经是 `theme.resolve()` 的**字面值**，本文件不再做变量展开；
 * - **R-EXP-2**：字体族/字号内联到克隆根（导出后不依赖页面 CSS）；
 * - **R-EXP-3**：PNG 流程 = 克隆 → `viewBox = plan.bounds` → 宽 3200px（高按比例）→ 清空选中层 →
 *   背景矩形用 `theme.resolve('canvas')`（替换原实现硬编码的画布色）→ `Image` → `canvas` → `toBlob`；
 * - **R-EXP-5**：SVG 文件头写 `<!-- generated by decoration-studio; units: mm -->`，并补 `xmlns`。
 */
import type { Bounds } from '@/types/geometry';
import type { TokenResolver } from '@/types/theme';

/** 渲染层组 id（与 `PlanCanvas.vue` 一致；导出时按 id 定位需要清空/替换的层） */
export const SVG_LAYER_IDS = {
  defs: 'defs',
  grid: 'gGrid',
  rooms: 'gRooms',
  furn: 'gFurn',
  walls: 'gWalls',
  open: 'gOpen',
  labels: 'gLabels',
  dims: 'gDims',
  measure: 'gMeasure',
  sel: 'gSel',
  edit: 'gEdit',
} as const;

/** 2D 图纸字体（原 `font-family` 写在 `<svg>` 上，L356） */
export const PLAN_FONT_FAMILY =
  '-apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif';

export interface PlanSvgExportOptions {
  /** 渲染后的 `<svg>` 节点（必须是本组件自己的 DOM，⛔ 不要传 3D 容器的兄弟节点） */
  svg: SVGSVGElement;
  /** 户型包围盒（`plan.bounds`） */
  bounds: Bounds;
  resolve: TokenResolver;
  /** 网格图层是否开启（决定导出底图用网格还是纯色） */
  gridOn?: boolean;
  /** 导出位图宽度（px，原 3200） */
  width?: number;
}

function cloneForExport(options: PlanSvgExportOptions): SVGSVGElement {
  const { svg, bounds, resolve, gridOn, width = 3200 } = options;
  const clone = svg.cloneNode(true) as SVGSVGElement;
  const height = Math.max(1, Math.round((width * bounds.h) / bounds.w));
  clone.setAttribute('viewBox', `${bounds.x} ${bounds.y} ${bounds.w} ${bounds.h}`);
  clone.setAttribute('width', String(width));
  clone.setAttribute('height', String(height));
  clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  clone.setAttribute('xmlns:xlink', 'http://www.w3.org/1999/xlink');
  clone.setAttribute('font-family', PLAN_FONT_FAMILY);

  // 选中层/编辑层不导出（原 L1885：`clone.querySelector('#gSel').innerHTML = ''`）
  for (const id of [SVG_LAYER_IDS.sel, SVG_LAYER_IDS.edit]) {
    const layer = clone.querySelector(`#${id}`);
    if (layer) layer.innerHTML = '';
  }

  // 背景：网格开时保留 `url(#grid)`（defs 里的网格已用令牌字面值），否则用 canvas 令牌
  const grid = clone.querySelector(`#${SVG_LAYER_IDS.grid}`);
  if (grid) {
    grid.innerHTML = `<rect x="-20000" y="-20000" width="55000" height="55000" fill="${
      gridOn ? 'url(#grid)' : resolve('canvas')
    }"/>`;
  }
  const background = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
  const attrs: Record<string, string> = {
    x: '-20000',
    y: '-20000',
    width: '55000',
    height: '55000',
    fill: resolve('canvas'),
  };
  for (const [key, value] of Object.entries(attrs)) background.setAttribute(key, value);
  if (grid) clone.insertBefore(background, grid);
  return clone;
}

/** 导出 SVG 文本（P0-6：矢量交付，零依赖；⛔ 不引入 html-to-image/modern-screenshot） */
export function serializePlanSvg(options: PlanSvgExportOptions): string {
  const clone = cloneForExport(options);
  const body = new XMLSerializer().serializeToString(clone);
  return `<?xml version="1.0" encoding="UTF-8"?>\n<!-- generated by decoration-studio; units: mm -->\n${body}`;
}

/** 导出 PNG（原 `exportPNG` 的 2D 分支，L1880-1897） */
export function planSvgToPng(options: PlanSvgExportOptions): Promise<Blob | null> {
  const clone = cloneForExport(options);
  const width = options.width ?? 3200;
  const height = Math.max(1, Math.round((width * options.bounds.h) / options.bounds.w));
  const serialized = new XMLSerializer().serializeToString(clone);
  const source = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(serialized)}`;
  return new Promise((resolvePromise) => {
    const image = new Image();
    image.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        resolvePromise(null);
        return;
      }
      ctx.drawImage(image, 0, 0, width, height);
      canvas.toBlob((blob) => resolvePromise(blob));
    };
    image.onerror = () => resolvePromise(null);
    image.src = source;
  });
}

/** 打包导出文件名（原 `tr('户型装修方案','floor-plan-design')`，L1894） */
export const EXPORT_BASENAME = '户型装修方案';

/** 触发下载（原 `download(name, blob)`，L1879：`URL.createObjectURL` + 1s 后回收） */
export function downloadBlob(name: string, blob: Blob): void {
  const anchor = document.createElement('a');
  anchor.href = URL.createObjectURL(blob);
  anchor.download = name;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(anchor.href), 1000);
}

/** 便捷入口：导出并下载 SVG */
export function exportPlanSvg(options: PlanSvgExportOptions): void {
  const svgText = serializePlanSvg(options);
  downloadBlob(`${EXPORT_BASENAME}.svg`, new Blob([svgText], { type: 'image/svg+xml;charset=utf-8' }));
}

/** 便捷入口：导出并下载 PNG（失败时返回 `false`，调用方负责提示） */
export async function exportPlanPng(options: PlanSvgExportOptions): Promise<boolean> {
  const blob = await planSvgToPng(options);
  if (!blob) return false;
  downloadBlob(`${EXPORT_BASENAME}.png`, blob);
  return true;
}